def files_area(path):
    p = str(path).replace('\\', '/').lower()
    if p.startswith('src/files.app/'):
        return 'main-winui-app'
    if p.startswith('src/files.app.controls/'):
        return 'shared-winui-controls'
    if p.startswith('src/files.app.cswin32/'):
        return 'native-interop'
    if p.startswith('src/files.app.storage/'):
        return 'app-storage'
    if p.startswith('src/files.core.storage/'):
        return 'core-storage'
    if p.startswith('src/files.shared/'):
        return 'shared-code'
    if p.startswith('src/files.core.sourcegenerator/'):
        return 'source-generator'
    if p.startswith('tests/'):
        return 'tests'
    if p.startswith('docs/'):
        return 'docs'
    if p.startswith('.github/'):
        return 'github-workflow'
    return 'unknown'

def files_verify_command(target, platform, configuration):
    t = str(target).lower()
    p = str(platform)
    c = str(configuration)
    if t == 'shared':
        project = 'src/Files.Shared/Files.Shared.csproj'
    elif t == 'sourcegenerator':
        project = 'src/Files.Core.SourceGenerator/Files.Core.SourceGenerator.csproj'
    elif t == 'app':
        project = 'src/Files.App/Files.App.csproj'
    else:
        project = 'Files.slnx'
    return 'msbuild -restore ' + project + ' -p:Configuration=' + c + ' -p:Platform=' + p + ' -v:quiet -clp:ErrorsOnly'
